gcz3(){return"\u062d\u062f\u0627\u0642\u0644 \u062f\u0631\u0635\u062f \u062a\u063a\u06cc\u06cc\u0631 \u0628\u0631\u0627\u06cc \u062b\u0628\u062a"},
gcyU(){return"\u0645\u0633\u062f\u0648\u062f \u06a9\u0631\u062f\u0646 \u0648\u0642\u062a\u06cc \u0627\u0633\u0646\u067e\u200c\u0634\u0627\u062a \u06a9\u0647\u0646\u0647 \u0627\u0633\u062a"},
gczv(){return"\u06a9\u0647\u0646\u06af\u06cc \u067e\u0633 \u0627\u0632 (\u0633\u0627\u0639\u062a)"},
gczh(){return"\u0622\u0641\u0633\u062a \u0647\u0631 \u0627\u0631\u0632"},
gczg(){return"\u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0628\u0627 \u0645\u0642\u0627\u062f\u06cc\u0631 \u0641\u0639\u0644\u06cc \u0641\u0631\u0645 (\u067e\u06cc\u0634\u200c\u0646\u0648\u06cc\u0633) \u0645\u062d\u0627\u0633\u0628\u0647 \u0645\u06cc\u200c\u0634\u0648\u062f. \u0628\u0631\u0627\u06cc \u0645\u0627\u0646\u062f\u06af\u0627\u0631\u06cc\u060c \u0630\u062e\u06cc\u0631\u0647 \u06a9\u0646\u06cc\u062f."},
gczm(){return"\u062a\u0627\u0632\u0647\u200c\u0633\u0627\u0632\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634"},
gcz7(){return"\u0627\u0631\u0632 \u0641\u0631\u0639\u06cc\u200c\u0627\u06cc \u06cc\u0627\u0641\u062a \u0646\u0634\u062f."},
gczd(){return"\u0646\u0648\u0639 \u0622\u0641\u0633\u062a"},
gczb(){return"\u0628\u062f\u0648\u0646 \u0622\u0641\u0633\u062a"},
gczc(){return"\u062f\u0631\u0635\u062f"},
gcz8(){return"\u0645\u0628\u0644\u063a \u062b\u0627\u0628\u062a"},
gcz9(){return"\u062c\u0647\u062a"},
gcze(){return"\u0628\u0627\u0644\u0627\u062a\u0631 \u0627\u0632 \u0628\u0627\u0632\u0627\u0631 (+)"},
gcza(){return"\u067e\u0627\u06cc\u06cc\u0646\u200c\u062a\u0631 \u0627\u0632 \u0628\u0627\u0632\u0627\u0631 (\u2212)"},
gczf(){return"\u0645\u0642\u062f\u0627\u0631"},
gczl(){return"\u0646\u0631\u062e \u0645\u0631\u062c\u0639"},
gcyX(){return"\u0646\u0631\u062e \u0646\u0647\u0627\u06cc\u06cc \u067e\u0633 \u0627\u0632 \u0622\u0641\u0633\u062a"},
gczk(){return"\u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0632\u0646\u062f\u0647 \u0627\u0632 \u0627\u0633\u0646\u067e\u200c\u0634\u0627\u062a \u0645\u0631\u06a9\u0632\u06cc \u0628\u0627 \u067e\u06cc\u0634\u200c\u0646\u0648\u06cc\u0633 \u0641\u0639\u0644\u06cc."},
gczp(){return"\u0627\u062c\u0631\u0627\u06cc \u0641\u0648\u0631\u06cc"},
gczn(){return"\u0647\u0645\u06af\u0627\u0645\u200c\u0633\u0627\u0632\u06cc \u0627\u0646\u062c\u0627\u0645 \u0634\u062f"},
gczw(){return"\u0632\u0645\u0627\u0646\u200c\u0628\u0646\u062f\u06cc \u0641\u0639\u0627\u0644"},
