gcz1(){return"\u0622\u062e\u0631\u06cc\u0646 \u0627\u062c\u0631\u0627"},
gcz6(){return"\u0627\u062c\u0631\u0627\u06cc \u0628\u0639\u062f\u06cc"},
cz2(a){return"\u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u062e\u0648\u062f\u06a9\u0627\u0631 \u0646\u0627\u0645\u0648\u0641\u0642: "+a},
czq(a){return"\u0630\u062e\u06cc\u0631\u0647 \u062a\u0646\u0638\u06cc\u0645\u0627\u062a \u062e\u0648\u062f\u06a9\u0627\u0631 \u0646\u0627\u0645\u0648\u0641\u0642: "+a},
czj(a){return"\u0628\u0627\u0631\u06af\u0630\u0627\u0631\u06cc \u067e\u06cc\u0634\u200c\u0646\u0645\u0627\u06cc\u0634 \u0646\u0627\u0645\u0648\u0641\u0642: "+a},
czo(a){return"\u0627\u062c\u0631\u0627\u06cc \u0647\u0645\u06af\u0627\u0645\u200c\u0633\u0627\u0632\u06cc \u0646\u0627\u0645\u0648\u0641\u0642: "+a},
