gcn7(){return"\u0648\u06cc\u0631\u0627\u06cc\u0634 \u0648\u06cc\u062c\u062a \u0686\u062a"},
gcn8(){return"\u0648\u06cc\u062c\u062a \u0686\u062a \u062c\u062f\u06cc\u062f"},
gcn6(){return"\u067e\u0633 \u0627\u0632 \u0627\u06cc\u062c\u0627\u062f\u060c \xab\u06a9\u0644\u06cc\u062f \u0639\u0645\u0648\u0645\u06cc\xbb \u0648 \u0631\u0627\u0647\u0646\u0645\u0627\u06cc \u0627\u062a\u0635\u0627\u0644 API \u0627\u0632 \u0645\u0646\u0648\u06cc \u2026 \u0648\u06cc\u062c\u062a \u0642\u0627\u0628\u0644 \u06a9\u067e\u06cc \u0627\u0633\u062a. \u062f\u0627\u0645\u0646\u0647\u0654 \u0645\u062c\u0627\u0632 \u0641\u0642\u0637 \u0627\u0645\u0646\u06cc\u062a \u0645\u0631\u0648\u0631\u06af\u0631 (CORS) \u0627\u0633\u062a."},
